#[derive(Clone)]
pub struct AppState {
    pub db: Arc<Mutex<Connection>>,
    pub moderator_username: Arc<str>,
    pub moderator_password: Arc<str>,
}

impl AppState {
    fn conn(&self) -> std::sync::MutexGuard<'_, Connection> {
        self.db.lock().unwrap_or_else(|e| e.into_inner())
    }
}

/// Errors that turn into HTTP responses.
enum AppError {
    NotFound,
    Db(rusqlite::Error),
}

impl From<rusqlite::Error> for AppError {
    fn from(e: rusqlite::Error) -> Self {
        AppError::Db(e)
    }
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        match self {
            AppError::NotFound => (StatusCode::NOT_FOUND, Html(views::not_found())).into_response(),
            AppError::Db(e) => {
                eprintln!("database error: {e}");
                (StatusCode::INTERNAL_SERVER_ERROR, "Something went wrong\n").into_response()
            }
        }
    }
}

type AppResult<T = Response> = Result<T, AppError>;

const CSS: &str = include_str!("../static/quizzy.css");
const FONT: &[u8] = include_bytes!("../static/Inter-latin.woff2");

#[tokio::main]
async fn main() {
    let port: u16 = std::env::var("PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(3000);
    let username = std::env::var("QUIZZY_MODERATOR_USERNAME").unwrap_or_default();
    let password = std::env::var("QUIZZY_MODERATOR_PASSWORD").unwrap_or_default();
    if username.is_empty() || password.is_empty() {
        eprintln!("warning: QUIZZY_MODERATOR_USERNAME / QUIZZY_MODERATOR_PASSWORD not set; the moderator area is locked");
    }
    let storage = std::env::var("QUIZZY_STORAGE").unwrap_or_else(|_| "storage".into());
    std::fs::create_dir_all(&storage).expect("create storage dir");
    let conn = db::open(&format!("{storage}/quizzy.sqlite3")).expect("open database");

    let state = AppState {
        db: Arc::new(Mutex::new(conn)),
        moderator_username: username.into(),
        moderator_password: password.into(),
    };

    let app = Router::new()
        .route("/", get(|| async { Html(views::home()) }))
        .route("/up", get(|| async { "OK" }))
        .route("/assets/quizzy.css", get(css))
        .route("/assets/Inter-latin.woff2", get(font))
        .merge(moderate_routes())
        .fallback(|| async { AppError::NotFound })
        // Guards every path under /moderate (including unknown ones) with Basic auth.
        .layer(middleware::from_fn_with_state(state.clone(), auth::require_moderator))
        .with_state(state);

    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    let listener = tokio::net::TcpListener::bind(addr).await.expect("bind");
    println!("Quizzy listening on http://{addr}");
    axum::serve(listener, app)
        .with_graceful_shutdown(async {
            let ctrl_c = tokio::signal::ctrl_c();
            let mut term = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("signal");
            tokio::select! { _ = ctrl_c => {}, _ = term.recv() => {} }
        })
        .await
        .expect("serve");
}

fn moderate_routes() -> Router<AppState> {
    Router::new()
        .route("/moderate", get(quiz_index))
        .route("/moderate/", get(|| async { Redirect::to("/moderate") }))
        .route("/moderate/quizzes", post(quiz_create))
