<script>
document.querySelectorAll("[data-active-form]").forEach(function (form) {{
  var box = form.querySelector("input[type=checkbox]");
  box.addEventListener("change", function () {{
    var body = new URLSearchParams();
    body.append("active", box.checked ? "1" : "0");
    box.disabled = true;
    fetch(form.action, {{ method: "POST", body: body, keepalive: true, headers: {{ "X-Requested-With": "fetch" }} }})
      .then(function (r) {{ if (!r.ok) throw new Error(r.status); }})
      .then(function () {{
        form.closest("[data-question]").classList.toggle("question-item--inactive", !box.checked);
        var n = 0;
        document.querySelectorAll("[data-question]").forEach(function (item) {{
          var on = item.querySelector("[data-active-form] input[type=checkbox]").checked;
          item.querySelector("[data-num]").textContent = on ? String(++n) : "—";
        }});
        var c = document.querySelector("[data-active-count]");
        if (c) c.textContent = String(n);
      }})
      .catch(function () {{ box.checked = !box.checked; alert("Couldn't save. Please try again."); }})
      .finally(function () {{ box.disabled = false; }});
  }});
}});
</script>"#,
            title = esc(&quiz.title),
            total = questions.len(),
        ),
    )
}

/// One row of the question form, as rendered.
pub struct OptionRow {
  }}
  document.querySelector("[data-add-option]").addEventListener("click", function (e) {{
    e.preventDefault();
    rows.appendChild(tpl.content.firstElementChild.cloneNode(true));
    renumber();
    var all = rows.querySelectorAll("input[type=text]");
    all[all.length - 1].focus();
  }});
  rows.addEventListener("click", function (e) {{
    var btn = e.target.closest("[data-remove-row]");
    if (!btn) return;
    btn.closest("[data-option-row]").remove();
    renumber();
  }});
}})();
</script>"#,
            title = esc(&quiz.title),
            body = esc(body),
            checked = if active { " checked" } else { "" },
            errors = errors_box(errors),
            template = option_row(0, &OptionRow { id: None, text: String::new(), correct: false }),
        ),
    )
}

fn play_layout(quiz: &Quiz, body: &str) -> String {
    format!(
        r#"{head}<body>
<div class="preview-banner"><span>Preview · answers aren’t saved</span><a href="/moderate/quizzes/{id}">Back to quiz</a></div>
<div class="play">
  <div class="play__top"><span class="logo play__logo"><span class="logo__mark">?</span>Quizzy</span><span>{title}</span></div>
  <div class="play__body play__body--top">
{body}
  </div>
</div>
</body></html>"#,
        head = head(&format!("Preview · {}", quiz.title)),
        id = quiz.id,
        title = esc(&quiz.title),
    )
}
"
}

